export function normalizeReviewerReadLogEvidence(input: unknown, label = 'readLog'): ReviewerReadLogEvidence {
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    throw new Error(`${label}: must be an object with filesReadFully, filesTriagedByName, summary, and digest`);
  }
  const record = input as Record<string, unknown>;
  const filesReadFully = normalizePathArray(record.filesReadFully, 'filesReadFully', label);
  const filesTriagedByName = normalizePathArray(record.filesTriagedByName, 'filesTriagedByName', label);
  const full = new Set(filesReadFully);
  for (const path of filesTriagedByName) {
    if (full.has(path)) {
      throw new Error(`${label}: duplicate path ${path} appears in both filesReadFully and filesTriagedByName`);
    }
  }
  if (!record.summary || typeof record.summary !== 'object' || Array.isArray(record.summary)) {
    throw new Error(`${label}.summary: must be an object with readCount and tokenCount`);
  }
  const summaryRecord = record.summary as Record<string, unknown>;
  const readCount = summaryRecord.readCount;
  if (typeof readCount !== 'number' || !Number.isInteger(readCount) || readCount < 0) {
    throw new Error(`${label}.summary.readCount: must be a non-negative integer`);
  }
  const rawTokenCount = summaryRecord.tokenCount;
  if (
    rawTokenCount !== null
    && (typeof rawTokenCount !== 'number' || !Number.isInteger(rawTokenCount) || rawTokenCount < 0)
  ) {
    throw new Error(`${label}.summary.tokenCount: must be a non-negative integer or null`);
  }
  if (typeof record.digest !== 'string' || !SHA256_HEX.test(record.digest)) {
    throw new Error(`${label}.digest: must be a sha256 hex digest`);
  }
  const tokenCount = rawTokenCount === null ? null : rawTokenCount;
  return {
    filesReadFully,
    filesTriagedByName,
    summary: {
      readCount,
      tokenCount,
    },
    digest: record.digest,
  };
}

export function normalizeReviewerReadDiagnostics(input: unknown, label = 'readDiagnostics'): ReviewerReadDiagnostic[] {
  if (!Array.isArray(input)) {
    throw new Error(`${label}: must be an array`);
  }
  const normalized = input.map((item, idx): ReviewerReadDiagnostic => {
    if (!item || typeof item !== 'object' || Array.isArray(item)) {
      throw new Error(`${label}[${idx}]: must be an object`);
    }
    const record = item as Record<string, unknown>;
    if (typeof record.code !== 'string' || !(REVIEWER_READ_DIAGNOSTIC_CODES as readonly string[]).includes(record.code)) {
      throw new Error(`${label}[${idx}].code: unsupported reviewer read diagnostic code`);
    }
    if (record.severity !== 'finding') {
      throw new Error(`${label}[${idx}].severity: must be "finding"`);
    }
    if (typeof record.message !== 'string' || record.message.trim().length === 0) {
      throw new Error(`${label}[${idx}].message: must be a non-empty string`);
    }
    const path = record.path === undefined
      ? undefined
      : normalizeRelativePath(record.path, `${label}[${idx}].path`);
    return {
      code: record.code as ReviewerReadDiagnostic['code'],
      severity: 'finding',
      message: record.message.trim(),
      ...(path ? { path } : {}),
    };
  });
  return normalized.sort((a, b) =>
    `${a.code}:${a.path ?? ''}:${a.message}`.localeCompare(`${b.code}:${b.path ?? ''}:${b.message}`),
  );
}

function addSetDiagnostics(
  diagnostics: ReviewerReadDiagnostic[],
  expected: readonly string[],
  actual: readonly string[],
  missingCode: ReviewerReadDiagnostic['code'],
  extraCode: ReviewerReadDiagnostic['code'],
  missingMessage: string,
  extraMessage: string,
): void {
  const expectedSet = new Set(expected);
  const actualSet = new Set(actual);
  for (const path of [...expectedSet].sort((a, b) => a.localeCompare(b))) {
    if (!actualSet.has(path)) {
      diagnostics.push({ code: missingCode, severity: 'finding', path, message: `${missingMessage}: ${path}` });
    }
  }
  for (const path of [...actualSet].sort((a, b) => a.localeCompare(b))) {
    if (!expectedSet.has(path)) {
      diagnostics.push({ code: extraCode, severity: 'finding', path, message: `${extraMessage}: ${path}` });
    }
  }
}

function decisionMarkdownPaths(paths: readonly string[], requirementsDir: string | undefined): string[] {
  return paths
    .filter(path => isDecisionMarkdownPath(path, { requirementsDir }))
    .sort((a, b) => a.localeCompare(b));
}

export function diagnoseReviewerReadEvidence(args: {
  readManifest: ReviewerReadManifest;
  readLog: ReviewerReadLogEvidence;
  knownDecisionFiles?: string[];
  requirementsDir?: string;
}): ReviewerReadDiagnostic[] {
  const readManifest = normalizeReviewerReadManifest(args.readManifest);
  const diagnostics: ReviewerReadDiagnostic[] = [];
  const readLogFilesReadFully = decisionMarkdownPaths(args.readLog.filesReadFully, args.requirementsDir);
  const readLogFilesTriagedByName = decisionMarkdownPaths(args.readLog.filesTriagedByName, args.requirementsDir);
  const manifestFilesReadFully = decisionMarkdownPaths(readManifest.filesReadFully, args.requirementsDir);
  const manifestFilesTriagedByName = decisionMarkdownPaths(readManifest.filesTriagedByName, args.requirementsDir);
  addSetDiagnostics(
    diagnostics,
    readLogFilesReadFully,
    manifestFilesReadFully,
    'read_manifest_missing_full_read',
    'read_manifest_extra_full_read',
    'mechanical decisions-doc read log has a full read missing from readManifest.filesReadFully',
    'readManifest.filesReadFully self-reports a decisions-doc file absent from the mechanical read log',
  );
  addSetDiagnostics(
    diagnostics,
    readLogFilesTriagedByName,
    manifestFilesTriagedByName,
    'read_manifest_missing_triage',
    'read_manifest_extra_triage',
    'mechanical decisions-doc read log has a triaged file missing from readManifest.filesTriagedByName',
    'readManifest.filesTriagedByName self-reports a decisions-doc file absent from the mechanical read log',
  );

  const knownDecisionFiles = (args.knownDecisionFiles ?? [])
    .map((path, idx) => normalizeRelativePath(path, `knownDecisionFiles[${idx}]`))
    .filter(path => isDecisionMarkdownPath(path, { requirementsDir: args.requirementsDir }))
    .sort((a, b) => a.localeCompare(b));
  const fullyRead = new Set(readLogFilesReadFully);
  const fullScanWithoutReason = knownDecisionFiles.length > 0
    && knownDecisionFiles.every(path => fullyRead.has(path))
    && readManifest.scanEscalationReason === null;
  if (fullScanWithoutReason) {
    diagnostics.push({
      code: 'full_scan_without_scanEscalationReason',
      severity: 'finding',
      message: 'Full decisions-doc scan was mechanically observed but readManifest.scanEscalationReason is null',
    });
  }
  return diagnostics;
}

/**
 * Managed-review proposals have no trusted tool-event stream at import time.
 * Their provider-authored manifest, log, and summary must therefore agree as a
 * single self-consistent statement before the normal candidate/read binding can
 * grant REVIEW evidence. Keep the ordinary reviewer diagnostic above scoped to
 * mechanical decision reads; this stricter projection is for the managed
 * receipt boundary only.
 */
export function diagnoseManagedReviewerReadEvidence(args: {
  readManifest: ReviewerReadManifest;
  readLog: ReviewerReadLogEvidence;
  requirementsDir?: string;
}): ReviewerReadDiagnostic[] {
  const manifest = normalizeReviewerReadManifest(args.readManifest);
  const log = normalizeReviewerReadLogEvidence(args.readLog);
  const diagnostics = diagnoseReviewerReadEvidence({
    readManifest: manifest,
    readLog: log,
    requirementsDir: args.requirementsDir,
  });
  // Unlike native read capture, the provider's terminal log is a compact
  // manifest of unique paths. Compare every claimed review artifact, not only
  // decisions docs, so a decision manifest cannot be paired with an unrelated
  // source-file log.
  addSetDiagnostics(
    diagnostics,
    log.filesReadFully,
    manifest.filesReadFully,
    'read_manifest_missing_full_read',
    'read_manifest_extra_full_read',
    'managed readLog.filesReadFully has a path missing from readManifest.filesReadFully',
    'managed readManifest.filesReadFully has a path absent from readLog.filesReadFully',
  );
  addSetDiagnostics(
    diagnostics,
    log.filesTriagedByName,
    manifest.filesTriagedByName,
    'read_manifest_missing_triage',
    'read_manifest_extra_triage',
    'managed readLog.filesTriagedByName has a path missing from readManifest.filesTriagedByName',
    'managed readManifest.filesTriagedByName has a path absent from readLog.filesTriagedByName',
  );
  if (log.summary.readCount !== log.filesReadFully.length) {
    diagnostics.push({
      code: 'read_manifest_extra_full_read',
      severity: 'finding',
      message: `managed readLog.summary.readCount (${log.summary.readCount}) must equal unique filesReadFully count (${log.filesReadFully.length})`,
    });
  }
  const seen = new Set<string>();
  return diagnostics.filter(diagnostic => {
    const key = `${diagnostic.code}:${diagnostic.path ?? ''}:${diagnostic.message}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}
  if (!existsSync(paths.spec) || !existsSync(paths.owner)) return null;
  const { text: specText, value: spec } = readManagedHostRunSpec(paths);
  const owner = readManagedHostRunOwner(paths);
  if (spec.schemaVersion !== MANAGED_HOST_RUN_SCHEMA_VERSION
    || owner.schemaVersion !== MANAGED_HOST_RUN_SCHEMA_VERSION
    || spec.runId !== paths.expectedRunId
    || owner.runId !== paths.expectedRunId
    || owner.specDigest !== sha256(specText)) {
    throw new Error(`managed host run ${runId}: immutable ownership subject binding mismatch`);
  }
  return typeof spec.storyId === 'string' && spec.storyId.trim().length > 0 ? spec.storyId.trim() : null;
}

type ManagedReviewFinalProposalInput = Omit<ManagedReviewEvidenceProposal, 'schemaVersion' | 'runId' | 'authoredAt'>;

function readValidManagedReviewEvidenceProposal(
  root: string,
  runId: string,
  spec: ManagedHostRunSpec,
): ManagedReviewEvidenceProposal | null {
  try {
    const proposal = readManagedReviewEvidenceProposal(root, runId);
    if (!proposal
      || proposal.schemaVersion !== 'lattice.managed_review_evidence_proposal.v1'
      || proposal.runId !== runId
      || proposal.storyId !== spec.storyId
      || proposal.providerAgent !== spec.agentType
      || proposal.lane !== spec.lane
      || proposal.reviewRunId !== spec.reviewRunId
      || !Number.isFinite(Date.parse(proposal.authoredAt))) {
      return null;
    }
    if (proposal.conclusion === 'pass') {
      if (typeof proposal.note !== 'string' || proposal.note.trim().length < 10
        || (proposal.findings !== undefined && (!Array.isArray(proposal.findings) || proposal.findings.length > 0))) {
        return null;
      }
    } else if (proposal.conclusion === 'findings') {
      if (typeof proposal.note === 'string' && proposal.note.trim().length > 0
        || !Array.isArray(proposal.findings)
        || proposal.findings.length === 0
        || !proposal.findings.every(isStrictManagedReviewFindingProposal)) {
        return null;
      }
    } else {
      return null;
    }
    if (!hasRequiredManagedReviewReadEvidence(proposal.readManifest, proposal.readLog)) return null;
    normalizeReviewerReadManifest(proposal.readManifest);
    normalizeReviewerReadLogEvidence(proposal.readLog);
    if (proposal.readDiagnostics !== undefined) normalizeReviewerReadDiagnostics(proposal.readDiagnostics);
    return proposal;
  } catch {
    return null;
  }
}

function parseManagedReviewFinalProposal(result: HostRunResult): ManagedReviewFinalProposalInput {
  if (result.finalAssistantResultTruncated) {
    throw new Error('managed_review_final_result_oversize');
  }
  if (result.finalAssistantResultCount > 1) {
    throw new Error('managed_review_final_result_multiple');
  }
  if (result.finalAssistantResultCount !== 1 || result.finalAssistantResult === null) {
    throw new Error('managed_review_final_result_missing');
  }
  const classification = classifyManagedReviewFinalEnvelope(result.finalAssistantResult);
  if (classification.kind !== 'valid') throw new Error('managed_review_final_result_malformed');
  const envelope = classification.envelope;
  const conclusion = envelope.conclusion;
  return {
    storyId: envelope.storyId,
    providerAgent: envelope.providerAgent,
    lane: envelope.lane,
    reviewRunId: envelope.reviewRunId,
    conclusion,
    ...(conclusion === 'pass' ? { note: envelope.note as string | undefined } : {
      findings: envelope.findings as ManagedReviewEvidenceFindingProposal[] | undefined,
    }),
    readManifest: envelope.readManifest as ReviewerReadManifest,
    readLog: envelope.readLog as unknown as ReviewerReadLogEvidence,
    ...(envelope.readDiagnostics !== undefined ? { readDiagnostics: envelope.readDiagnostics as ReviewerReadDiagnostic[] } : {}),
  };
}

export function writeManagedReviewEvidenceProposal(args: {
  root: string;
  runId: string;
  proposal: Omit<ManagedReviewEvidenceProposal, 'schemaVersion' | 'runId' | 'authoredAt'>;
  environment?: NodeJS.ProcessEnv;
  providerInvocationPid?: number;
  providerInvocationAttestation?: ManagedReviewProposalInvocationAttestation;
}): ManagedReviewEvidenceProposal {
  // Compatibility ingress is provider-authored input too. Keep it under the
  // same bounded final-envelope ceiling as the canonical adapter path before
  // any filesystem or authority side effect.
  if (Buffer.byteLength(canonicalJson(args.proposal), 'utf8') > HOST_RUN_FINAL_ASSISTANT_RESULT_CAP) {
    throw new Error(`managed_review_proposal_set: proposal exceeds ${HOST_RUN_FINAL_ASSISTANT_RESULT_CAP} byte managed final envelope cap`);
  }
  const paths = pathsFor(args.root, args.runId);
  const spec = readManagedHostRunSpec(paths).value;
  const owner = readManagedHostRunOwner(paths);
  const snapshot = readManagedHostRunSnapshot(paths);
  const environment = args.environment ?? process.env;
  if (args.providerInvocationPid === undefined
    && args.providerInvocationAttestation === undefined
    && environment.LATTICE_MANAGED_HOST_RUN_ID !== args.runId) {
    throw new Error('managed_review_proposal_set: active managed-run capability is missing or mismatched');
  }
  if (readTerminal(paths) || snapshot.state !== 'running') {
